create extension if not exists pgcrypto;
create type public.app_role as enum ('user','artist','admin');
create type public.publication_status as enum ('draft','pending','approved','rejected','changes_requested','removed');
create table public.countries(id text primary key,name text not null unique,region text not null default 'Africa');
insert into public.countries(id,name) values('SS','South Sudan'),('KE','Kenya'),('UG','Uganda'),('TZ','Tanzania'),('NG','Nigeria'),('GH','Ghana') on conflict do nothing;
create table public.genres(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique);
insert into public.genres(name,slug) values('Afrobeats','afrobeats'),('Afro-fusion','afro-fusion'),('Gospel','gospel'),('Hip-hop','hip-hop'),('R&B','r-and-b'),('Traditional','traditional') on conflict do nothing;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,avatar_path text,country_id text references public.countries(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_roles(user_id uuid references auth.users(id) on delete cascade,role public.app_role not null default 'user',created_at timestamptz not null default now(),primary key(user_id,role));
create table public.artists(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null,slug text not null unique,biography text,country_id text references public.countries(id),avatar_path text,status public.publication_status not null default 'pending',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index artists_owner_idx on public.artists(owner_id); create index artists_country_idx on public.artists(country_id,status);
create table public.artist_genres(artist_id uuid references public.artists(id) on delete cascade,genre_id uuid references public.genres(id),primary key(artist_id,genre_id));
create table public.albums(id uuid primary key default gen_random_uuid(),artist_id uuid not null references public.artists(id) on delete cascade,title text not null,cover_path text,release_date date,status public.publication_status not null default 'pending',created_at timestamptz not null default now());
create table public.songs(id uuid primary key default gen_random_uuid(),artist_id uuid not null references public.artists(id) on delete cascade,album_id uuid references public.albums(id) on delete set null,title text not null,genre_id uuid references public.genres(id),country_id text references public.countries(id),release_date date,status public.publication_status not null default 'pending',created_at timestamptz not null default now());
create index songs_search_idx on public.songs using gin(to_tsvector('simple',title)); create index songs_discovery_idx on public.songs(country_id,genre_id,status,release_date desc);
create table public.song_sources(id uuid primary key default gen_random_uuid(),song_id uuid not null references public.songs(id) on delete cascade,provider text not null check(provider in('youtube','licensed_audio','official_link')),provider_id text,external_url text,storage_path text,is_embeddable boolean not null default false,license_reference text,permission_verified_at timestamptz,created_at timestamptz not null default now(),check((provider='licensed_audio' and storage_path is not null and license_reference is not null and permission_verified_at is not null) or provider<>'licensed_audio'));
create table public.artist_submissions(id uuid primary key default gen_random_uuid(),artist_id uuid not null references public.artists(id) on delete cascade,song_id uuid references public.songs(id) on delete set null,declaration_accepted_at timestamptz not null,status public.publication_status not null default 'pending',reviewer_id uuid references auth.users(id),reviewer_note text,reviewed_at timestamptz,created_at timestamptz not null default now());
create table public.playlists(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null check(length(name) between 1 and 80),description text,is_public boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.playlist_songs(playlist_id uuid references public.playlists(id) on delete cascade,song_id uuid references public.songs(id) on delete cascade,position integer not null check(position>=0),added_at timestamptz not null default now(),primary key(playlist_id,song_id),unique(playlist_id,position));
create table public.favourites(user_id uuid references auth.users(id) on delete cascade,song_id uuid references public.songs(id) on delete cascade,artist_id uuid references public.artists(id) on delete cascade,created_at timestamptz not null default now(),check((song_id is null) <> (artist_id is null)),unique(user_id,song_id),unique(user_id,artist_id));
create table public.trending_charts(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null,country_id text references public.countries(id),genre_id uuid references public.genres(id),period_start date not null,period_end date not null,source_note text not null default 'Platform editorial chart',is_official boolean not null default false,published boolean not null default false,created_at timestamptz not null default now(),check(period_end>=period_start));
create table public.trending_chart_entries(chart_id uuid references public.trending_charts(id) on delete cascade,song_id uuid references public.songs(id) on delete cascade,artist_id uuid references public.artists(id) on delete cascade,rank integer not null check(rank>0),primary key(chart_id,rank),check((song_id is null) <> (artist_id is null)));
create table public.promotional_campaigns(id uuid primary key default gen_random_uuid(),artist_id uuid not null references public.artists(id) on delete cascade,title text not null,placement text not null check(placement in('featured_artist','sponsored_placement','release_announcement','profile_enhancement','event_promotion')),status text not null default 'draft' check(status in('draft','pending_payment','scheduled','active','ended','cancelled')),starts_at timestamptz,ends_at timestamptz,sponsored_label text not null default 'Sponsored',created_at timestamptz not null default now());
create table public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,plan_key text not null,provider text,provider_subscription_id text,status text not null default 'pending' check(status in('pending','active','past_due','cancelled','expired')),currency text,amount_minor bigint check(amount_minor>=0),created_at timestamptz not null default now());
create table public.payment_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),campaign_id uuid references public.promotional_campaigns(id),subscription_id uuid references public.subscriptions(id),provider text not null,provider_reference text unique,status text not null default 'pending' check(status in('pending','verified','failed','refunded')),currency text not null,amount_minor bigint not null check(amount_minor>=0),verified_at timestamptz,created_at timestamptz not null default now(),check((campaign_id is null) <> (subscription_id is null)));
create table public.music_events(id uuid primary key default gen_random_uuid(),organizer_id uuid not null references auth.users(id),title text not null,description text,country_id text references public.countries(id),venue text,starts_at timestamptz not null,status public.publication_status not null default 'pending',created_at timestamptz not null default now());
create table public.content_reports(id uuid primary key default gen_random_uuid(),reporter_id uuid references auth.users(id) on delete set null,song_id uuid references public.songs(id) on delete cascade,artist_id uuid references public.artists(id) on delete cascade,reason text not null,status text not null default 'open' check(status in('open','reviewing','resolved','dismissed')),created_at timestamptz not null default now(),check((song_id is null) <> (artist_id is null)));
create table public.copyright_reports(id uuid primary key default gen_random_uuid(),reporter_id uuid references auth.users(id) on delete set null,song_id uuid references public.songs(id) on delete set null,claimant_email text not null,details text not null,status text not null default 'open' check(status in('open','reviewing','resolved','dismissed')),created_at timestamptz not null default now());
create table public.platform_settings(key text primary key,value jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create function public.has_role(r public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role=r) $$;
revoke all on function public.has_role(public.app_role) from public; grant execute on function public.has_role(public.app_role) to authenticated;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name','')); insert into public.user_roles(user_id,role) values(new.id,'user'); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
do $$ declare t text; begin foreach t in array array['countries','genres','profiles','user_roles','artists','artist_genres','albums','songs','song_sources','artist_submissions','playlists','playlist_songs','favourites','trending_charts','trending_chart_entries','promotional_campaigns','subscriptions','payment_transactions','music_events','content_reports','copyright_reports','platform_settings'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy countries_read on public.countries for select to anon,authenticated using(true); create policy genres_read on public.genres for select to anon,authenticated using(true);
create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid() or public.has_role('admin')); create policy profiles_update on public.profiles for update to authenticated using(id=auth.uid() or public.has_role('admin')) with check(id=auth.uid() or public.has_role('admin'));
create policy roles_read on public.user_roles for select to authenticated using(user_id=auth.uid() or public.has_role('admin'));
create policy artists_read on public.artists for select to anon,authenticated using(status='approved' or owner_id=auth.uid() or public.has_role('admin')); create policy artists_insert on public.artists for insert to authenticated with check(owner_id=auth.uid() and status='pending'); create policy artists_update on public.artists for update to authenticated using(owner_id=auth.uid() and status in('pending','changes_requested')) with check(owner_id=auth.uid() and status in('pending','changes_requested'));
create policy songs_read on public.songs for select to anon,authenticated using(status='approved' or exists(select 1 from public.artists a where a.id=artist_id and a.owner_id=auth.uid()) or public.has_role('admin')); create policy songs_insert on public.songs for insert to authenticated with check(status='pending' and exists(select 1 from public.artists a where a.id=artist_id and a.owner_id=auth.uid()));
create policy albums_read on public.albums for select to anon,authenticated using(status='approved' or exists(select 1 from public.artists a where a.id=artist_id and a.owner_id=auth.uid()) or public.has_role('admin'));
create policy sources_read on public.song_sources for select to anon,authenticated using(exists(select 1 from public.songs s where s.id=song_id and s.status='approved' and (provider<>'licensed_audio' or permission_verified_at is not null)) or public.has_role('admin'));
create policy playlists_read on public.playlists for select to anon,authenticated using(is_public or owner_id=auth.uid() or public.has_role('admin')); create policy playlists_insert on public.playlists for insert to authenticated with check(owner_id=auth.uid()); create policy playlists_update on public.playlists for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid()); create policy playlists_delete on public.playlists for delete to authenticated using(owner_id=auth.uid());
create policy playlist_songs_read on public.playlist_songs for select to anon,authenticated using(exists(select 1 from public.playlists p where p.id=playlist_id and(p.is_public or p.owner_id=auth.uid() or public.has_role('admin')))); create policy playlist_songs_write on public.playlist_songs for all to authenticated using(exists(select 1 from public.playlists p where p.id=playlist_id and p.owner_id=auth.uid())) with check(exists(select 1 from public.playlists p where p.id=playlist_id and p.owner_id=auth.uid())); create policy favourites_own on public.favourites for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy charts_read on public.trending_charts for select to anon,authenticated using(published or public.has_role('admin')); create policy chart_entries_read on public.trending_chart_entries for select to anon,authenticated using(exists(select 1 from public.trending_charts c where c.id=chart_id and(c.published or public.has_role('admin'))));
create policy submissions_read on public.artist_submissions for select to authenticated using(exists(select 1 from public.artists a where a.id=artist_id and a.owner_id=auth.uid()) or public.has_role('admin')); create policy submissions_insert on public.artist_submissions for insert to authenticated with check(declaration_accepted_at is not null and status='pending' and exists(select 1 from public.artists a where a.id=artist_id and a.owner_id=auth.uid()));
create policy campaigns_admin on public.promotional_campaigns for all to authenticated using(public.has_role('admin')) with check(public.has_role('admin')); create policy campaigns_owner_read on public.promotional_campaigns for select to authenticated using(exists(select 1 from public.artists a where a.id=artist_id and a.owner_id=auth.uid()));
create policy subscriptions_read on public.subscriptions for select to authenticated using(user_id=auth.uid() or public.has_role('admin')); create policy transactions_read on public.payment_transactions for select to authenticated using(user_id=auth.uid() or public.has_role('admin'));
create policy events_read on public.music_events for select to anon,authenticated using(status='approved' or organizer_id=auth.uid() or public.has_role('admin')); create policy events_insert on public.music_events for insert to authenticated with check(organizer_id=auth.uid() and status='pending');
create policy report_insert on public.content_reports for insert to authenticated with check(reporter_id=auth.uid()); create policy copyright_insert on public.copyright_reports for insert to anon,authenticated with check(true); create policy report_admin_read on public.content_reports for select to authenticated using(public.has_role('admin')); create policy copyright_admin_read on public.copyright_reports for select to authenticated using(public.has_role('admin'));
create policy settings_read on public.platform_settings for select to anon,authenticated using(key in('public_brand','public_features')); create policy settings_admin on public.platform_settings for all to authenticated using(public.has_role('admin')) with check(public.has_role('admin'));
-- Bootstrap the initial administrator manually in the trusted SQL Editor after email verification:
-- insert into public.user_roles(user_id,role) select id,'admin' from auth.users where email='YOUR_VERIFIED_ADMIN_EMAIL';
do $$ declare t text; begin foreach t in array array['profiles','user_roles','artists','artist_genres','albums','songs','song_sources','artist_submissions','playlists','playlist_songs','favourites','trending_charts','trending_chart_entries','promotional_campaigns','subscriptions','payment_transactions','music_events','content_reports','copyright_reports','platform_settings'] loop execute format('create policy administrator_all on public.%I for all to authenticated using(public.has_role(''admin'')) with check(public.has_role(''admin''))',t); end loop; end $$;
